import pathlib,re

def inspect_masters(pidfile):
 path=pathlib.Path(pidfile);previous=pathlib.Path(str(path)+'.oldbin')
 def role(pid):
  try:return (pathlib.Path('/proc')/str(pid)/'cmdline').read_bytes().split(b'\0')[0].decode()
  except (FileNotFoundError,ProcessLookupError,UnicodeError) as exc:raise ValueError('missing or unreadable process') from exc
 def master(file):
  try:text=file.read_text().strip()
  except (OSError,UnicodeError) as exc:raise ValueError('missing or invalid pidfile') from exc
  if re.fullmatch(r'[1-9][0-9]{0,9}',text) is None:raise ValueError('positive ASCII PID required')
  pid=int(text)
  if not role(pid).startswith('nginx: master process '):raise ValueError('not a live nginx master')
  return pid
 def workers(pid):
  try:children=(pathlib.Path('/proc')/str(pid)/'task'/str(pid)/'children').read_text().split()
  except OSError as exc:raise ValueError('master disappeared') from exc
  result=[]
  for text in children:
   child=int(text)
   try:description=role(child)
   except ValueError:continue
   if description.startswith('nginx: worker process'):result.append(child)
  return sorted(result)
 active=master(path);old=None
 if previous.exists():
  old=master(previous)
  if old==active:raise ValueError('old and active master cannot be identical')
 active_workers=workers(active);old_workers=workers(old) if old is not None else []
 phase='single_master' if old is None else 'dual_masters' if old_workers else 'old_workers_quiesced'
 return {'active_master':active,'old_master':old,'active_workers':active_workers,'old_workers':old_workers,'phase':phase}
```

原题知识说明：
重载主要使master读取配置并替换worker，热升级二进制涉及新master及监听继承。需按部署方式确认支持的USR2、WINCH、QUIT流程、PID文件和旧master存续，并验证模块ABI、版本及长连接；在旧进程仍可恢复前验证新worker服务。systemd或容器管理可能改变流程，不能简单并行启动另一个占同端口程序。

